    function campaignActionForStatus(status){if(status==='ENABLED')return{operation:'pause_campaign',verb:'pausar',title:'Confirmar pausa',buttonLabel:'Pausar campanha'};if(status==='PAUSED')return{operation:'enable_campaign',verb:'ativar',title:'Confirmar ativação',buttonLabel:'Ativar campanha'};return null}
