        if(pendingCampaignAction!==item||!campaignActionDialog.open)return;
        if(configuration.customerId!==item.customerId||configuration.managerCustomerId!==item.managerCustomerId)throw new Error('A configuração retornada pertence a outra conta ou MCC. Nenhuma ação foi liberada.');
