    function evaluateCampaignClicksWithoutSalePauseRule(snapshot,clicks){const threshold=Number.isSafeInteger(clicks)&&clicks>=0&&clicks<=99?clicks:autoPauseClicksWithoutSaleSettings.clicks,candidates=[];let missingClicksCount=0,protectedSales=0;for(const row of snapshot?.rows||[]){if(row?.c?.apiSnapshotOnly===true||row?.c?._status==='historico')continue;const info=row?.googleAdsCampaignAction||{};if(String(info.campaignStatus||'').toUpperCase()!=='ENABLED')continue;const totals=row?.consolidatedTotals,observedClicks=totals?.observed?.clicks,campaignClicks=totals?.clicks;if(!Number.isSafeInteger(campaignClicks)||campaignClicks<0||!Number.isSafeInteger(observedClicks)||observedClicks<1){missingClicksCount++;continue}if(campaignClicks<threshold)continue;if(row.hasDiarySale){protectedSales++;continue}const linked=info.mappingStatus==='mapped'&&/^[0-9]{10}$/.test(String(info.managerCustomerId||''))&&/^[0-9]{10}$/.test(String(info.customerId||''))&&/^[1-9]\d{0,19}$/.test(String(info.campaignId||''));candidates.push({rule:'clicks_without_sale',row,internalCampaignId:String(row.campaignId||''),managerCustomerId:String(info.managerCustomerId||''),customerId:String(info.customerId||''),campaignId:String(info.campaignId||''),accountName:String(info.accountName||row.account||''),managerName:String(info.managerName||row.mcc||''),campaignName:String(info.campaignName||row.c?.nome_campanha_exato||row.identity?.name||'Campanha'),product:String(row.productLabel||row.c?.nome_exibicao||row.identity?.name||'Produto não identificado'),clicks:campaignClicks,thresholdClicks:threshold,status:'ENABLED',observedAt:String(info.observedAt||''),captureSavedAt:String(info.captureCapturedAtUtc||''),linked})}candidates.sort((a,b)=>a.clicks-b.clicks||a.campaignName.localeCompare(b.campaignName,'pt-BR',{numeric:true,sensitivity:'base'}));return{clicks:threshold,candidates,protectedSales,missingClicksCount}}
