    function updateAutoPauseServerQueueCountdowns(){const now=Date.now();autoPauseServerQueueList?.querySelectorAll('[data-auto-pause-server-cancel-until]').forEach(node=>{const deadline=parseAutoPauseServerQueueTimestamp(node.dataset.autoPauseServerCancelUntil),remaining=deadline-now,button=node.closest('li')?.querySelector('[data-auto-pause-server-cancel]');if(!Number.isFinite(deadline)){node.textContent='Prazo de cancelamento não informado.';if(button)button.disabled=true;return}if(remaining<=0){node.textContent='Prazo para cancelar encerrado.';if(button)button.disabled=true;return}const seconds=Math.ceil(remaining/1000),minutes=Math.floor(seconds/60),rest=seconds%60;node.textContent=`Cancelamento disponível por mais ${minutes?`${minutes} min `:''}${rest} s.`})}
