    function automaticPauseReason(record,campaignId){
      let source=record;
      if(!source?.rule){const events=(presentationSnapshot?.autoPauseHistory||[]).filter(event=>String(event.campaignId||'')===String(campaignId||'')),confirmedAt=Date.parse(record?.confirmedAtUtc||''),matchingEvent=Number.isFinite(confirmedAt)?events.find(event=>Date.parse(event.occurredAtUtc||'')===confirmedAt):events[0];source=matchingEvent||source}
      switch(source?.rule){case'negative_remaining':return'Valor restante negativo';case'product_performance':return'Desempenho do mesmo produto';case'minimum_product_performance':return'Concorrente pausada após a referência atingir os mínimos de impressões e cliques';case'reference_competitor':return'Concorrente mais próxima da referência por impressões';case'campaign_age':return Number.isSafeInteger(source.thresholdDays)&&source.thresholdDays>0?`Campanha acima do limite de ${fmtNum(source.thresholdDays)} dias${Number.isSafeInteger(source.maxImpressions)&&source.maxImpressions>=0?` e até ${fmtNum(source.maxImpressions)} impressões`:''}`:'Campanha acima do limite de dias';case'campaign_zero_impressions':return'Dias sem impressões';case'clicks_without_sale':return Number.isSafeInteger(source.thresholdClicks)&&source.thresholdClicks>=0?`Limite de ${fmtNum(source.thresholdClicks)} cliques acumulados sem venda`:'Limite de cliques sem venda';default:return'Motivo não registrado'}
    }
