    function formatAutomaticPauseTimestamp(value){const instant=new Date(value);if(!Number.isFinite(instant.getTime()))return'';return new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(instant)}
    function overviewCampaignFilterState(row){
      if(stalePreviewActive)return{filterStatus:row?.filterStatus||row?.c?._status||'',autoPauseConfirmedAtUtc:row?.autoPauseConfirmedAtUtc||'',actionStatus:row?.actionStatus||''};
      const internalId=String(row?.campaignId||''),sourceInfo=row?.googleAdsCampaignAction||{},stored=row?.c||{},info={
        ...sourceInfo,
        managerCustomerId:String(sourceInfo.managerCustomerId||stored.mcc_id||'').replace(/\D/g,''),
        customerId:String(sourceInfo.customerId||stored.conta_id||'').replace(/\D/g,''),
        campaignId:String(sourceInfo.campaignId||stored.google_ads_campaign_id||''),
      };
      const statusRow={...row,googleAdsCampaignAction:info},memoryOverride=campaignActionOverrides.get(internalId),persistedOverride=readPersistedCampaignActionStatusOverride(statusRow),appliedKey=autoPauseCampaignKey(info),applied=appliedKey?autoPauseAppliedHistory.get(appliedKey):null;
      const diaryPauseAt=(presentationSnapshot?.autoPauseHistory||[]).filter(event=>String(event?.campaignId||'')===internalId).reduce((latest,event)=>{const at=Date.parse(event?.occurredAtUtc||'');return Number.isFinite(at)?Math.max(latest,at):latest},0);
      const resolution=global.CampaignStatusDomain.resolveCampaignStatus({fallbackStatus:stored._status||'ativa',apiStatus:info.campaignStatus||stored.google_ads_current_configuration?.campaignStatus||'',apiObservedAt:info.observedAt||stored.google_ads_current_configuration?.observedAtUtc||'',captureSavedAt:info.captureCapturedAtUtc||'',identity:info,memoryOverride,persistedOverride,automaticPauseAt:applied?.confirmedAtUtc,diaryPauseAt});
      return{filterStatus:resolution.status,autoPauseConfirmedAtUtc:resolution.autoPauseCurrent?new Date(resolution.autoPauseAt).toISOString():'',actionStatus:resolution.actionStatus};
    }
